import unittest
from reference import normalize_reference

class ReferenceTests(unittest.TestCase):
    def test_normalize(self):
        self.assertEqual(normalize_reference(" ab12cd "), "AB12CD")
    def test_reject_short(self):
        with self.assertRaises(ValueError):
            normalize_reference("abc")
    def test_reject_punctuation(self):
        with self.assertRaises(ValueError):
            normalize_reference("AB-123")

if __name__ == "__main__":
    unittest.main()
